/**
 * Dashboard UI translation engine — mirrors the AR experience's STRINGS/t()
 * pattern (see NavMe Experience navmeI18n.ts) instead of pulling in a library.
 */
import { NAVME_LANGUAGES } from './languages.js';

const STORAGE_KEY = 'navme_dashboard_lang';
const DEFAULT_LANG = 'en';
const FALLBACK_ACRONYMS = new Map([
  ['api', 'API'],
  ['ar', 'AR'],
  ['csv', 'CSV'],
  ['fps', 'FPS'],
  ['id', 'ID'],
  ['pdf', 'PDF'],
  ['poi', 'POI'],
  ['pois', 'POIs'],
  ['qr', 'QR'],
  ['url', 'URL'],
  ['xyz', 'XYZ'],
]);

function humanizeKey(key) {
  const tail = String(key).split('.').at(-1) ?? String(key);
  const words = tail
    .replace(/([A-Z]+)([A-Z][a-z])/g, '$1 $2')
    .replace(/([a-z0-9])([A-Z])/g, '$1 $2')
    .split(/[\s_-]+/)
    .filter(Boolean);
  if (!words.length) return String(key);
  return words
    .map((word, index) => {
      const lower = word.toLowerCase();
      if (FALLBACK_ACRONYMS.has(lower)) return FALLBACK_ACRONYMS.get(lower);
      const normalized = index === 0 ? lower[0].toUpperCase() + lower.slice(1) : lower;
      return normalized;
    })
    .join(' ');
}

