  'facilityPanel.categoryAddedToast': { en: 'Category “{name}” added', es: 'Categoría “{name}” añadida', fr: 'Catégorie « {name} » ajoutée', ar: 'تمت إضافة الفئة “{name}”', zh: '分类“{name}”已添加', ja: 'カテゴリ“{name}”を追加しました', hi: 'श्रेणी “{name}” जोड़ी गई', kn: 'ವರ್ಗ “{name}” ಸೇರಿಸಲಾಗಿದೆ', pt: 'Categoria “{name}” adicionada', ta: 'வகை “{name}” சேர்க்கப்பட்டது', te: 'వర్గం “{name}” జోడించబడింది', ml: 'വിഭാഗം “{name}” ചേർത്തു', bn: 'বিভাগ “{name}” যোগ করা হয়েছে' },
