  'stairsPanel.scaleHeightLabel': { en: 'Scale H', es: 'Escala Alt.', fr: 'Échelle H', ar: 'مقياس الارتفاع', zh: '缩放高度', ja: 'スケール高さ', hi: 'स्केल ऊँचाई', kn: 'ಸ್ಕೇಲ್ ಎತ್ತರ', pt: 'Escala Alt', ta: 'அளவு உயரம்', te: 'స్కేల్ ఎత్తు', ml: 'സ്കെയിൽ ഉയരം', bn: 'স্কেল উচ্চতা' },
  'stairsPanel.alwaysOpenNote': { en: 'This marker helps navigation avoid stairs for wheelchair users and always stays open.', es: 'Este marcador ayuda a la navegación a evitar escaleras para usuarios de silla de ruedas y siempre permanece abierto.', fr: 'Ce marqueur aide la navigation à éviter les escaliers pour les utilisateurs de fauteuil roulant et reste toujours ouvert.', ar: 'تساعد هذه العلامة التنقل على تجنب الدرج لمستخدمي الكراسي المتحركة وتبقى مفتوحة دائمًا.', zh: '此标记帮助导航为轮椅用户避开楼梯，并始终保持开放。', ja: 'このマーカーは車椅子利用者のために階段を回避するナビゲーションを助け、常に開放されています。', hi: 'यह मार्कर व्हीलचेयर उपयोगकर्ताओं के लिए सीढ़ियों से बचने में नेविगेशन की मदद करता है और हमेशा खुला रहता है।', kn: 'ಈ ಮಾರ್ಕರ್ ಗಾಲಿಕುರ್ಚಿ ಬಳಕೆದಾರರಿಗೆ ಮೆಟ್ಟಿಲುಗಳನ್ನು ತಪ್ಪಿಸಲು ನ್ಯಾವಿಗೇಶನ್‌ಗೆ ಸಹಾಯ ಮಾಡುತ್ತದೆ ಮತ್ತು ಯಾವಾಗಲೂ ತೆರೆದಿರುತ್ತದೆ.', pt: 'Este marcador ajuda a navegação a evitar escadas para usuários de cadeira de rodas e permanece sempre aberto.', ta: 'இந்த குறிப்பான் சக்கர நாற்காலி பயனர்களுக்கு படிக்கட்டுகளைத் தவிர்க்க வழிசெலுத்தலுக்கு உதவுகிறது, எப்போதும் திறந்திருக்கும்.', te: 'ఈ మార్కర్ వీల్‌చైర్ వినియోగదారుల కోసం మెట్లను నివారించడానికి నావిగేషన్‌కు సహాయపడుతుంది మరియు ఎల్లప్పుడూ తెరిచి ఉంటుంది.', ml: 'വീൽചെയർ ഉപയോക്താക്കൾക്ക് പടികൾ ഒഴിവാക്കാൻ നാവിഗേഷനെ സഹായിക്കുന്ന ഈ മാർക്കർ എപ്പോഴും തുറന്നിരിക്കും.', bn: 'এই মার্কার হুইলচেয়ার ব্যবহারকারীদের জন্য সিঁড়ি এড়াতে নেভিগেশনে সাহায্য করে এবং সবসময় খোলা থাকে।' },
  'stairsPanel.deleteTitle': { en: 'Delete', es: 'Eliminar', fr: 'Supprimer', ar: 'حذف', zh: '删除', ja: '削除', hi: 'हटाएँ', kn: 'ಅಳಿಸಿ', pt: 'Excluir', ta: 'நீக்கு', te: 'తొలగించండి', ml: 'നീക്കം ചെയ്യുക', bn: 'মুছুন' },
