let currentLang = readStoredLang();
const listeners = new Set();
const translatedTextNodes = new WeakMap();
const translatedAttributes = new WeakMap();
const LOCALIZED_ATTRIBUTES = ['aria-label', 'title', 'placeholder', 'alt'];

function buildTranslationLookup() {
  const forward = new Map();
  const reverse = new Map();
  Object.values(STRINGS).forEach((row) => {
    const english = String(row?.en ?? '');
    if (!english) return;
    const translated = String(row[currentLang] ?? english);
    if (!forward.has(english) || forward.get(english) === english) forward.set(english, translated);
    if (translated && !reverse.has(translated)) reverse.set(translated, english);
    if (!reverse.has(english)) reverse.set(english, english);
  });
  return { forward, reverse };
}

function translateRenderedValue(value, lookup, previous) {
  const current = String(value ?? '');
  const previousRender = previous?.rendered;
  const rendered = previous && current === previousRender ? previous.original : current;
  const leading = rendered.match(/^\s*/)?.[0] ?? '';
  const trailing = rendered.match(/\s*$/)?.[0] ?? '';
  const content = rendered.slice(leading.length, rendered.length - trailing.length || undefined);
  const original = lookup.reverse.get(content) ?? content;
  const translated = lookup.forward.get(original) ?? original;
  return {
    original,
    rendered: `${leading}${translated}${trailing}`,
  };
}

function refreshRenderedTranslations() {
  if (!document.body) return;
  const lookup = buildTranslationLookup();
  const walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT);
  let node;

  while ((node = walker.nextNode())) {
    const parent = node.parentElement;
    if (!parent || /^(SCRIPT|STYLE|NOSCRIPT|TEXTAREA|CODE|PRE)$/.test(parent.tagName)) continue;
    const state = translateRenderedValue(node.nodeValue, lookup, translatedTextNodes.get(node));
    translatedTextNodes.set(node, state);
    if (node.nodeValue !== state.rendered) node.nodeValue = state.rendered;
  }

  document.body.querySelectorAll('*').forEach((element) => {
    const attributes = translatedAttributes.get(element) ?? new Map();
    LOCALIZED_ATTRIBUTES.forEach((name) => {
      if (!element.hasAttribute(name)) return;
      const state = translateRenderedValue(
        element.getAttribute(name),
        lookup,
        attributes.get(name),
      );
      attributes.set(name, state);
      if (element.getAttribute(name) !== state.rendered) {
        element.setAttribute(name, state.rendered);
      }
    });
    translatedAttributes.set(element, attributes);
  });
}

function readStoredLang() {
  try {
    const stored = window.localStorage.getItem(STORAGE_KEY);
    if (stored && NAVME_LANGUAGES.some((l) => l.code === stored)) return stored;
  } catch {
    /* localStorage unavailable (SSR/privacy mode) — fall back to default */
  }
  return DEFAULT_LANG;
}

export function getLanguage() {
  return currentLang;
}

export function isRTL(code = currentLang) {
  return code === 'ar';
}

export function applyDirection(code = currentLang) {
  const rtl = isRTL(code);
  document.documentElement.dir = rtl ? 'rtl' : 'ltr';
  document.documentElement.lang = code;
  document.body?.classList.toggle('rtl', rtl);
}

export function setLanguage(code) {
  const valid = NAVME_LANGUAGES.some((l) => l.code === code) ? code : DEFAULT_LANG;
  currentLang = valid;
  try {
    window.localStorage.setItem(STORAGE_KEY, valid);
  } catch {
    /* ignore storage failures */
  }
  applyDirection(valid);
  refreshRenderedTranslations();
  listeners.forEach((handler) => handler(valid));
}

export function onLanguageChange(handler) {
  listeners.add(handler);
  return () => listeners.delete(handler);
}

/**
 * @param {string} key
 * @param {Record<string, string|number>} [params]
 */
export function t(key, params) {
  const row = STRINGS[key];
  let text = row ? (row[currentLang] ?? row.en) : humanizeKey(key);
  if (text == null) text = humanizeKey(key);
  if (params) {
    for (const p of Object.keys(params)) {
      text = text.split(`{${p}}`).join(String(params[p]));
    }
  }
  return text;
}

/**
 * Resolve DB-stored content (POI names, descriptions, category names) for the
 * active language. Rows carry one column per language (`poi_name_es`, …) which
 * the data layer folds into a `{ lang: text }` map; fall back to English and
 * then the raw source text when a language is still untranslated.
 * @param {Record<string, string> | null | undefined} langMap
 * @param {string} [fallback]
 */
export function localizedText(langMap, fallback = '') {
  const map = langMap && typeof langMap === 'object' ? langMap : null;
  const pick = (code) => String(map?.[code] ?? '').trim();
  return pick(currentLang) || pick(DEFAULT_LANG) || String(fallback ?? '').trim();
}

// Initialize <html dir/lang> as soon as this module loads.
applyDirection(currentLang);
